   "lead": "Lo spagnolo Alejandro Davidovich Fokina, numero 26 del ranking, ha eliminato il tedesco Alexander Zverev, prima testa di serie, nel torneo Masters di Shanghai. Il match si è concluso 5-7, 6-4, 6-3 dopo una rimonta dello spagnolo. In finale affronterà il vincente tra Daniil Medvedev e Rafael Jodar. Lo riferisce Al Jazeera.",
