   "lead": "Il Chelsea ha sconfitto 2-0 l'Everton in Premier League grazie a una doppietta di Pedro Neto, salendo al quarto posto in classifica. La partita è stata però segnata dall'infortunio alla testa del portiere argentino dell'Everton Emiliano Martinez, uscito in barella e trasportato in ospedale dopo uno scontro di gioco. Il calciatore, secondo fonti sudamericane, si è ripreso ma è stato sostituito. Lo riportano Guardian e CNA, con rilanci anche dalla stampa argentina.",
