   "orig": "Snøhetta completes landmark opera house in Shanghai",
   "lead": "Lo studio internazionale Snøhetta ha completato il Shanghai Grand Opera House, un edificio di 146.786 metri quadrati situato sul lungofiume Huangpu. La struttura, dotata di tre sale per spettacoli, è caratterizzata da una gigantesca scala a spirale che conduce i visitatori fino al tetto pubblico, pensato come destinazione civica oltre che sede culturale. L'opera è stata presentata come un nuovo punto di riferimento architettonico per la città cinese. Lo riferisce Dezeen, con conferme da Domus, Designboom e Wallpaper*.",
