   "lead": "Migliaia di manifestanti hanno sfilato a Roma da piazza della Repubblica a piazza del Popolo per il corteo 'La Via maestra', promosso dalla Cgil con gli slogan «lavoro, pace, Costituzione». Alla manifestazione hanno partecipato anche i leader del cosiddetto campo largo dell'opposizione. Il segretario Maurizio Landini, che ha chiuso il corteo, ha accusato il governo di investire solo sulle armi. Lo riferiscono ANSA e la Repubblica.",
