   "titolo": "La siccità minaccia il Lago Salato della Turchia",
   "orig": "Drought threatens wildlife and livelihoods at Turkey’s Salt Lake",
   "lead": "Il Tuz Gölü, secondo lago più grande della Turchia e situato nell'Anatolia centrale a circa 150 chilometri da Ankara, affronta una crisi idrica causata dalla siccità e dal pompaggio eccessivo di acque sotterranee per l'agricoltura. Il lago, tra i più salati al mondo, è un importante sito di riproduzione per la fauna selvatica e sostiene anche produzione di sale e turismo locale. Lo riferisce Turkish Minute.",
   "more": [
    "I laghi salati come il Tuz Gölü si formano in bacini chiusi senza sfogo verso il mare, rendendoli particolarmente vulnerabili ai cambiamenti nel bilancio idrico causati da siccità prolungate e dallo sfruttamento agricolo intensivo delle falde acquifere circostanti."
   ],
