   "orig": "Dentro un campeggio sulle Dolomiti c’è un ristorante con 1.500 vini in cantina: è tra i migliori d’Italia",
   "lead": "Sul lago di Dobbiaco, nelle Dolomiti, Andreas Panzenberger ha aperto il ristorante Hebbo all'interno del campeggio di famiglia, dedicandolo al padre Herbert. La cucina alpina si fonde con influenze peruviane, mentre la cantina, forte di 1.500 etichette, ha conquistato il massimo riconoscimento delle Tre Bottiglie nella guida Ristoranti d'Italia 2027 del Gambero Rosso. Lo riferisce Gambero Rosso.",
