   "sez": "ambiente",
   "titolo": "Le api domestiche scacciano gli impollinatori selvatici dai fiori",
   "orig": "Honeybees are barging aside wild pollinators in hunt for pollen and nectar, study finds",
   "lead": "Uno studio dell'Università Anglia Ruskin ha dimostrato che le api domestiche, in forte aumento per la crescita dell'apicoltura, competono aggressivamente con gli impollinatori selvatici come bombi e api solitarie, spingendoli via dai fiori. I ricercatori hanno riscontrato che nelle aree con maggiore concentrazione di api domestiche si registra una minore presenza di specie selvatiche rivali. Lo riferisce The Guardian.",
   "more": [
    "Gli impollinatori selvatici svolgono un ruolo ecologico distinto da quello delle api domestiche gestite dagli apicoltori; il loro declino, se confermato da ulteriori studi, potrebbe avere conseguenze sulla biodiversità vegetale e sulla resilienza degli ecosistemi naturali."
   ],
