   "orig": "Liam Gallagher non vuole i Fontaines D.C. in apertura agli Oasis: «Non sono abbastanza bravi»",
   "lead": "Il cantante degli Oasis Liam Gallagher ha dichiarato su X che i Fontaines D.C. «non sono abbastanza bravi» per aprire i concerti della band nel tour 'Live '27'. Il commento è arrivato il giorno dell'uscita del nuovo album della band irlandese, 'Dopamine Chamber', e rappresenta l'ultimo episodio di una polemica tra i due gruppi che dura dal 2024. Lo riferiscono Rolling Stone Italia e NME.",
