   "id": "z855d4f1c",
   "sez": "ambiente",
   "titolo": "Il Cile attiva pienamente la sua normativa contro l'inquinamento luminoso",
   "orig": "Chile’s Light-Pollution Standard Takes Full Effect",
   "lead": "Il Cile, paese che ospita alcuni dei principali osservatori astronomici mondiali, ha reso operativa in tutto il territorio la sua normativa sull'inquinamento luminoso, dal deserto di Atacama alla Terra del Fuoco. La misura punta a proteggere la qualità dei cieli notturni, fondamentale per la ricerca astronomica svolta nel paese. Lo riferisce Sky & Telescope.",
   "more": [
    "Il deserto di Atacama, grazie alla sua altitudine e all'aridità estrema, ospita alcuni dei telescopi più avanzati al mondo; l'inquinamento luminoso dovuto all'espansione urbana rappresenta una minaccia crescente per l'osservazione astronomica in tutto il pianeta."
   ],
