   "id": "z752b7a5b",
   "sez": "italia",
   "titolo": "Papa Leone pronto a tornare a casa dopo i controlli medici",
   "orig": "Papa Leone è pronto a tornare a casa",
   "lead": "Papa Leone è stato autorizzato a rientrare in Vaticano dopo che i medici gli hanno dato il via libera al termine di esami clinici e di una radiografia al torace. L'annuncio arriva dopo accertamenti sanitari che avevano richiesto il ricovero del pontefice. Non sono stati forniti ulteriori dettagli sulle condizioni di salute che hanno portato ai controlli né sulla struttura in cui si sono svolti gli esami. Lo riferisce Rai News.",
   "more": [],
