   "titolo": "Fotografa 72enne vince il World Nature Photography Award con uno scatto di giraffe",
   "orig": "Vaidehi Chandrasekar, 72, wins global nature photography gold for giraffe shot",
   "lead": "Vaidehi Chandrasekar, fotografa indiana di 72 anni, ha vinto l'oro al World Nature Photography Award 2026 con uno scatto intitolato 'Water Ballet', che ritrae una giraffa mentre beve acqua in Botswana. L'immagine mette in luce i movimenti fluidi dell'animale, esaltati dai riflessi del sole sull'acqua. Chandrasekar si dedica alla fotografia naturalistica dal 2019, anno del suo ritiro dal lavoro, con l'obiettivo di promuovere la sensibilizzazione verso la conservazione ambientale attraverso le sue immagini. Lo riferisce Times of India.",
