   "sez": "cucina",
   "titolo": "Lo smash burger, moda di oggi che affonda le radici cent'anni fa",
   "orig": "Lo smash burger che oggi va di moda esisteva già 100 anni fa. Era il panino povero degli operai americani",
   "lead": "Lo smash burger, panino con carne di manzo schiacciata sulla piastra divenuto virale su TikTok e nelle hamburgerie contemporanee, ha in realtà una storia che risale a un secolo fa, quando era il cibo povero degli operai americani. La preparazione era un cardine delle tavole calde statunitensi, come lo storico diner White Mana di Jersey City, e si legava anche a tradizioni regionali come quella delle cipolle tipiche dell'Oklahoma. Lo riferisce Gambero Rosso.",
   "more": [
    "Lo smash burger prevede che la carne venga schiacciata direttamente sulla piastra rovente durante la cottura, creando una crosta caramellata esterna che negli ultimi anni ha reso questa tecnica un fenomeno virale sui social."
   ],
