   "orig": "Ci sono anche i Justice nella super colonna sonora di ‘Grand Theft Auto VI’",
   "lead": "Il duo musicale francese Justice ha composto parte della colonna sonora di Grand Theft Auto VI, il nuovo capitolo della celebre saga videoludica. Nel trailer di lancio del gioco compare 'Flower in a Hurricane', nuovo singolo del duo realizzato in collaborazione con Tame Impala, SZA e King Gizzard & the Lizard Wizard. La notizia conferma l'attenzione crescente dell'industria videoludica verso collaborazioni musicali di alto profilo per accompagnare il lancio di produzioni attese.",
