   "titolo": "Il Sud Sudan introduce un sistema di autorizzazione ai viaggi dei funzionari",
   "orig": "Kiir establishes prior approval system for officials’ travel",
   "lead": "Il presidente del Sud Sudan Salva Kiir Mayardit ha abolito le precedenti restrizioni generali ai viaggi per i funzionari governativi, sostituendole con un nuovo sistema che richiede un'autorizzazione preventiva per i viaggi all'estero e una notifica scritta per gli spostamenti interni al paese. La misura riguarda sia i funzionari in servizio che quelli in pensione, secondo quanto riportato dalle fonti sudsudanesi. Il provvedimento mira a regolamentare in modo più strutturato gli spostamenti del personale pubblico. Lo riferiscono Radio Tamazuj ed Eye Radio.",
