   "sez": "viaggi",
   "titolo": "Dinant, la città belga incastrata tra fiume e roccia che sembra un'illusione",
   "orig": "Una chiesa schiacciata tra il fiume e una parete immensa: la città europea che sembra un’illusione",
   "lead": "Nel sud del Belgio, lungo una delle anse più scenografiche del fiume Mosa, si trova Dinant, una città che appare incastrata tra l'acqua e una parete rocciosa verticale. Le case colorate si affacciano sul fiume quasi in fila, mentre dietro si innalza la falesia calcarea che sostiene un'imponente cittadella. Ai piedi della roccia si trova anche una chiesa, schiacciata tra il corso d'acqua e la parete. Lo riferisce Turisti per Caso.",
   "more": [
    "Dinant è una città vallona nota per il paesaggio lungo la Mosa e per essere il luogo natale di Adolphe Sax, inventore del saxofono. La cittadella che domina l'abitato ha origini medievali ed è stata più volte ricostruita nei secoli."
   ],
