   "sez": "ambiente",
   "titolo": "Specie esotiche avvistate al largo della California per un El Niño insolitamente forte",
   "orig": "Exotic species appear off California thanks to an unusually strong El Nino",
   "lead": "Al largo delle coste della California sono stati avvistati esemplari di specie marine esotiche come squali balena e squali martello, un fenomeno attribuito a un El Niño particolarmente intenso. Le acque più calde avrebbero favorito la migrazione di specie normalmente non presenti in quella zona. Gli avvistamenti recenti hanno attirato l'attenzione di biologi marini e appassionati, che osservano con interesse gli effetti del fenomeno climatico sull'ecosistema costiero statunitense. Lo riferisce The Straits Times.",
   "more": [
    "El Niño è un fenomeno climatico ciclico che provoca un riscaldamento anomalo delle acque superficiali del Pacifico, con conseguenze su correnti marine, clima globale e distribuzione delle specie marine, spingendo talvolta animali tropicali verso latitudini più settentrionali."
   ],
