   "titolo": "ChinaAid lancia l'allarme sulla salute del pastore cinese imprigionato",
   "orig": "ChinaAid raises alarm over imprisoned Chinese pastor's health as family seeks answers",
   "lead": "L'organizzazione ChinaAid ha espresso preoccupazione per le condizioni di salute del pastore cinese Wang Yi, detenuto in un carcere in Cina. Secondo il fondatore di ChinaAid, Bob Fu, sarebbero giunte notizie credibili secondo cui l'uomo soffrirebbe di un cancro al fegato in fase avanzata, ma tali informazioni non possono essere verificate in modo indipendente. La famiglia del pastore, noto per la sua attività religiosa non autorizzata dal governo cinese, cerca risposte sulle sue condizioni. Lo riferisce Fox News.",
   "more": [
    "Wang Yi è un noto pastore cristiano cinese, fondatore della Early Rain Covenant Church, una chiesa non registrata dalle autorità di Pechino. È stato condannato nel 2019 a nove anni di carcere per reati legati alla sua attività religiosa indipendente, in un contesto di repressione delle chiese non statali in Cina."
   ],
