   "lead": "È stato pubblicato il trailer del film celebrativo per il decimo anniversario della serie Aikatsu Stars, che rivela anche la canzone tema. Il film, intitolato legato al tema delle idol, vedrà la protagonista Yume e le sue compagne invitate a un evento chiamato Venus Jamboree insieme alle migliori idol del mondo. L'uscita nelle sale giapponesi è fissata per il 22 gennaio. Lo riferisce Anime News Network.",
