   "id": "zaa271921",
   "sez": "spazio",
   "titolo": "Mercurio resterà un enigma finché non verrà inviata una sonda in grado di atterrarvi",
   "orig": "Enigmatic Mercury Will Remain A Puzzle Until Someone Sends A Lander",
   "lead": "Nonostante l'imminente visita della missione BepiColombo a Mercurio, secondo un'analisi pubblicata da Universe Today il pianeta più interno del sistema solare continuerà a rimanere in gran parte un mistero scientifico. Gli autori sostengono che solo l'invio di una sonda capace di atterrare sulla sua superficie permetterebbe di comprendere a fondo le caratteristiche di questo pianeta, ancora poco conosciuto rispetto agli altri corpi del sistema solare. Lo riferisce Universe Today.",
   "more": [
    "BepiColombo è una missione congiunta dell'Agenzia Spaziale Europea e di quella giapponese lanciata nel 2018, diretta verso Mercurio per studiarne composizione, campo magnetico e storia geologica. Finora nessuna sonda è mai atterrata sulla superficie del pianeta, le cui condizioni estreme di temperatura e vicinanza al Sole rendono le missioni particolarmente complesse."
   ],
