   "id": "z11a49368",
   "sez": "sport",
   "titolo": "Gli attacchi Houthi frenano i sogni sportivi dell'Arabia Saudita",
   "orig": "Houthi conflict casts shadow as Saudi Arabia scales back sporting pipe dreams",
   "lead": "Lunedì sera una partita della Champions League asiatica Elite tra l'Al-Nassr e gli uzbeki del Neftchi Fergana è stata ritardata da allarmi per un attacco missilistico. Alla fine l'Al-Nassr, allenato da Ange Postecoglou, ha vinto 3-1, con un gol di Cristiano Ronaldo, affiancato da Sadio Mané. Davanti a un pubblico scarso, Ronaldo ha sventolato una sciarpa con i colori sauditi in segno di sfida. Gli attacchi degli Houthi contro obiettivi strategici stanno però frenando le ambizioni sportive ed economiche di Riad.",
   "more": [
    "Negli ultimi anni l'Arabia Saudita ha investito molto nello sport, portando nel suo campionato campioni come Cristiano Ronaldo e ospitando grandi eventi internazionali. Questa strategia punta a migliorare l'immagine del Paese e a diversificare un'economia legata al petrolio. Gli Houthi sono un movimento armato yemenita sostenuto dall'Iran."
   ],
