   "sez": "viaggi",
   "titolo": "Turismo, a Roma un manifesto per il futuro del settore tra record di presenze e impatto sul Pil",
   "orig": "Turismo, dal record di presenze all’impatto sul Pil: a Roma il manifesto per il futuro",
   "lead": "A Roma, al Tempio di Venere presso il Colosseo, si tiene a partire dalle 11 un'iniziativa dedicata al turismo, promossa dal ministero del Turismo in collaborazione con Il Sole 24 Ore. Al centro dell'incontro un manifesto per il futuro del settore, con un'analisi che va dal record di presenze al contributo del turismo al prodotto interno lordo. Tra gli interventi previsti figurano quelli del ministro Giammarco Mazzi e dell'amministratore delegato del Gruppo Il Sole 24 Ore, Federico Silvestri. L'appuntamento punta a delineare le prospettive di un comparto centrale per l'economia italiana. Lo riferisce Il Sole 24 Ore.",
   "more": [
    "Il Tempio di Venere e Roma è uno dei più grandi templi dell'antica Roma e sorge nell'area archeologica tra il Foro Romano e il Colosseo. Il turismo è uno dei settori più importanti dell'economia italiana, grazie al patrimonio artistico, storico e paesaggistico del Paese."
   ],
