   "id": "z2d712fbf",
   "sez": "cucina",
   "titolo": "Matrimoni costosi: e se la torta arrivasse dal supermercato?",
   "orig": "Weddings are expensive. How about a grocery store cake?",
   "lead": "Sposarsi costa caro, e una parte delle coppie cerca di risparmiare proprio sul dolce. Secondo il sito di organizzazione di matrimoni Zola, circa un terzo dei futuri sposi è disposto a contenere la spesa per la torta e i dessert, anche ricorrendo a soluzioni come le torte acquistate al supermercato. Il dato racconta come il peso dei costi delle nozze spinga molte coppie a rivedere le voci tradizionali del ricevimento, scegliendo alternative più economiche per uno degli elementi simbolo della festa. Lo riferisce NPR.",
   "more": [
    "La torta nuziale è uno dei simboli più tradizionali del ricevimento di matrimonio, spesso realizzata su più piani da pasticcerie specializzate e tagliata dagli sposi davanti agli invitati. Proprio per la sua elaborazione può rappresentare una voce di spesa significativa nel budget delle nozze."
   ],
